import{_ as t,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"春节策划丨快来挑战一下自己的分析逻辑吧！","description":"","frontmatter":{},"headers":[],"relativePath":"性能测试实战30讲/春节策划丨快来挑战一下自己的分析逻辑吧！.md","filePath":"性能测试实战30讲/春节策划丨快来挑战一下自己的分析逻辑吧！.md","lastUpdated":1779819911000}'),r={name:"性能测试实战30讲/春节策划丨快来挑战一下自己的分析逻辑吧！.md"};function o(i,_,s,l,n,d){return a(),e("div",null,[..._[0]||(_[0]=[p('<h1 id="春节策划丨快来挑战一下自己的分析逻辑吧" tabindex="-1">春节策划丨快来挑战一下自己的分析逻辑吧！ <a class="header-anchor" href="#春节策划丨快来挑战一下自己的分析逻辑吧" aria-label="Permalink to &quot;春节策划丨快来挑战一下自己的分析逻辑吧！&quot;">​</a></h1><p>Hi，我之前给你出了一套试卷，不知道你答得怎么样了呢？</p><p>今天我们继续来挑战！</p><p>在性能测试分析的过程中，有两个关键点是做分析的人必须要关注的，第一点就是，在压力工具执行完成之后，要学会判断瓶颈是否出现，以及是否应该继续加压。其次，在分析中，要学会分段会层，如果发现是某个节点出现了问题，就要学会从已有问题的计数器顺藤摸瓜找到具体的证据链。</p><p>要想做到这一点，就需要有基础知识的积累和清晰的判断思路。</p><p>鉴于此，选择题之外，我又想了两道主观题，帮助你复习一下我们之前讲到的核心思路。</p><ol><li>从压力工具中的响应时间和TPS图，如何判断出性能瓶颈？说明判断逻辑。</li><li>从操作系统的us CPU高或者wa CPU高，如何判断出根本原因，请画出你的分析逻辑证据链。</li></ol><p>你可以从专栏的第2篇、第6篇和第17篇找到相关的线索。</p><p>这是一个可简单、可复杂的主观题。在面试中，我经常会问到这样的问题，一般来说，回答都会反应出面试者的综合能力。有的人可能三两句就说完了，那显然功底不够，而有的人会有很多的经验可以分享，逻辑清晰。本专栏从前到后都在描述着一个完整的分析蓝图，而这个蓝图就是靠证据链来完成的。</p><p>所以对这个题目的回答就体现了你对性能分析理念的理解程度。</p><p>把你想到的判断逻辑放到GitHub上吧！我会查看这些答案，与你一起交流！</p>',11)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
